namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps =
            [
                "Preheat oven to 475°F (245°C).",
                "Roll out pizza dough on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until crust is golden.",
                "Top with fresh basil and a drizzle of olive oil."
            ],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps =
            [
                "Cook spaghetti in salted boiling water until al dente.",
                "Fry pancetta until crispy.",
                "Whisk eggs with grated Pecorino and pepper.",
                "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.",
                "Serve immediately with extra cheese and pepper."
            ],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps =
            [
                "Marinate chicken in yogurt and spices for at least 1 hour.",
                "Grill or broil chicken until lightly charred.",
                "Sauté onion, garlic, and ginger until softened.",
                "Add tomato sauce and spices, simmer for 15 minutes.",
                "Stir in cream, add chicken, and simmer 10 more minutes.",
                "Serve over basmati rice with naan bread."
            ],
            AverageRating = 4.7, RatingCount = 36
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with vegetables, tofu, and a tangy sauce.",
            Ingredients = ["Rice noodles", "Firm tofu", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Soy sauce", "Tamarind paste", "Brown sugar"],
            Steps =
            [
                "Soak rice noodles in warm water for 20 minutes, then drain.",
                "Press and cube tofu, then pan-fry until golden.",
                "Mix tamarind paste, soy sauce, and brown sugar for the sauce.",
                "Stir-fry vegetables until tender-crisp.",
                "Add noodles and sauce, toss until well coated.",
                "Serve topped with peanuts, bean sprouts, and lime wedges."
            ],
            AverageRating = 4.3, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps =
            [
                "Brown ground beef in a skillet, drain excess fat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm tortillas in a dry pan or microwave.",
                "Fill tortillas with seasoned beef.",
                "Top with lettuce, tomato, cheese, sour cream, and salsa."
            ],
            AverageRating = 4.2, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Individual cakes with a warm, gooey chocolate center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps =
            [
                "Preheat oven to 425°F (220°C). Grease ramekins.",
                "Melt chocolate and butter together.",
                "Whisk eggs and sugar until thick, fold into chocolate mixture.",
                "Add flour and vanilla, mix until just combined.",
                "Pour into ramekins and bake for 12–14 minutes.",
                "Invert onto plates and serve immediately."
            ],
            AverageRating = 4.9, RatingCount = 55
        },
        new()
        {
            Id = 7, Title = "Greek Salad", Category = "Salads",
            Description = "Fresh Mediterranean salad with crisp vegetables and tangy feta.",
            Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Red wine vinegar", "Oregano"],
            Steps =
            [
                "Chop cucumber, tomatoes, and red onion into bite-sized pieces.",
                "Combine vegetables in a large bowl.",
                "Add olives and crumbled feta cheese.",
                "Whisk olive oil, vinegar, and oregano for the dressing.",
                "Drizzle dressing over salad and toss gently."
            ],
            AverageRating = 4.1, RatingCount = 15
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Description = "Classic creamy avocado dip with lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps =
            [
                "Halve and pit avocados, scoop into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in diced onion, tomato, jalapeño, and cilantro.",
                "Add lime juice and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            AverageRating = 4.6, RatingCount = 28
        }
    ];

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars is < 1 or > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void Submit(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };
        _recipes.Add(recipe);
    }
}

